<script setup lang="ts">
import { ref } from 'vue';import { api } from '../../services/api';const title=ref('');const content=ref('');const mode=ref('REVIEW');const hours=ref(48);const working=ref(false);
async function publish(){if(!title.value||!content.value)return uni.showToast({title:'请填写标题和要求',icon:'none'});working.value=true;try{const dto={title:title.value,content:content.value,level:'IMPORTANT',completionMode:mode.value,feedbackRequired:mode.value==='REVIEW',attachmentRequired:false,deadlineAt:new Date(Date.now()+hours.value*3600000).toISOString(),assigneeSelection:{mode:'ALL_ACTIVE'}};const preview:any=await api('/tasks/assignee-preview','POST',dto.assigneeSelection);const ok=await new Promise<boolean>(resolve=>uni.showModal({title:'确认发布',content:`将向 ${preview.assigneeCount} 人发布任务。`,success:r=>resolve(r.confirm)}));if(!ok)return;const draft:any=await api('/tasks','POST',dto);await api(`/tasks/${draft.id}/publish`,'POST');uni.showToast({title:'发布成功',icon:'success'});setTimeout(()=>uni.navigateBack(),500);}catch(e:any){uni.showToast({title:e.message,icon:'none'});}finally{working.value=false;}}
</script><template><view class="page"><view class="card form"><text>任务标题</text><input v-model="title" placeholder="请输入标题"/><text>任务要求</text><textarea v-model="content" placeholder="请输入执行要求"/><text>完成方式</text><picker :range="['REVIEW','SIMPLE']" @change="mode=['REVIEW','SIMPLE'][Number($event.detail.value)]"><view class="picker">{{mode==='REVIEW'?'提交后审核':'点击即完成'}}</view></picker><text>完成时限（小时）</text><input v-model.number="hours" type="number"/></view><button class="primary-btn" :loading="working" @tap="publish">预览并发布</button></view></template><style scoped>.form>text{display:block;margin:22rpx 0 10rpx;font-weight:700}.form input,.form textarea,.picker{padding:20rpx;border:1px solid #dce7e8;border-radius:14rpx;background:#f8fbfb}.form textarea{min-height:300rpx}</style>
